function () {
  if (/(^|\.)dilytics\.ch$/.test({{Page Hostname}})) return 'prod';
  return {{Debug Mode}} ? 'preview' : 'off';
}

function () {
  var t = {{DLV - page_type}};
  if (t === 'service') return 'Services - ' + {{DLV - service_category}};
  return {home: 'Accueil', category: 'Catégories', contact: 'Contact', about: 'À propos', articles: 'Articles', jobs: 'Emploi', payment: 'Paiement', legal: 'Pages légales', not_found: 'Page introuvable'}[t] || 'Autres pages';
}

function () {
  if ({{DLV - link_location}} === 'site-nav') return 'v0wrCMOYkqAYEMmDo9wo';
  if ({{Page Path}} === '/') return 'dgbPCOqYkqAYEMmDo9wo';
  return 'kVpUCMCYkqAYEMmDo9wo';
}

function () {
  var e = {{DLV - ecommerce}} || {};
  var items = e.items || [];
  var o = {
    content_type: 'product',
    content_ids: items.map(function (i) { return i.item_id; }),
    contents: items.map(function (i) { return { id: i.item_id, quantity: i.quantity || 1 }; }),
    num_items: items.length
  };
  if (items[0]) { o.content_name = items[0].item_name; o.content_category = items[0].item_category; }
  if (e.value !== undefined) { o.value = e.value; o.currency = e.currency; }
  return o;
}

function () {
  var p = {{DLV - user_data.phone_number}};
  return p ? String(p).replace(/\D/g, '') : undefined;
}
